import { Show } from "solid-js";
/**
 * @file app.tsx
 * @copyright 2025, Firaxis Games
 * @description Main Solid.js application entry point for the game UI.
 * This file initializes all Solid.js components that need to be rendered globally.
 */
import { render } from "solid-js/web";

import { FocusViewer } from "#core/ui-next/debug/focus-viewer/focus-viewer.jsx";
import { createSignalFromDebugWidget } from "#core/ui-next/utilities/debug-widgets.js";

import { PlotTooltip } from "#base/ui-next/tooltips/plot-tooltip/plot-tooltip.jsx";

/**
 * Main application component that renders all global Solid.js UI components.
 */
function App() {
	const focusViewerEnabled = createSignalFromDebugWidget({
		caption: "Enable Focus Viewer",
		category: "Systems",
		domainType: "bool",
		id: "enableFocusViewer",
		value: false,
	});

	return (
		<>
			<PlotTooltip />
			<Show when={focusViewerEnabled()}>
				<FocusViewer initialVisibility={true} />
			</Show>
		</>
	);
}

/**
 * Initializes the Solid.js application and renders it into the DOM.
 * Should be called after the DOM is ready.
 */
export function InitApp() {
	const root = document.getElementById("solidjs-root");
	if (!root) {
		console.error("app.tsx: Could not find #solidjs-root element to mount Solid.js app");
		return;
	}

	render(() => <App />, root);
}
